import {escape,renderBlocks,categories} from '/cms-render.mjs';
import {createRichEditor,htmlToTree} from '/rich-editor.mjs';
import {seoulDate,validateTree} from '/content-document.mjs';
import {publicCMSConfig} from '/cms-config.mjs';
const $=s=>document.querySelector(s),form=$('#post-form');
let config=publicCMSConfig,session,current,blocks=[],assets=[],posts=[],dirty=false,busy=false,refreshing;
const urls=new Map();
let rich, richBaseline, loadingRich=false, selectedImage, initialPost;
let bodyState='idle',loadPhase='idle',confirmedPost=false;
function applyEditorState(){for(const s of ['#publish','#save-draft','#archive','#preview','#restore-post','#optimize-existing','#cover-upload','#remove-cover','#pdf-upload','#body-images','#add-faq'])$(s).disabled=busy||bodyState!=='ready';}
function requireReady(){if(bodyState!=='ready'||!rich)throw new Error('본문을 정상적으로 불러온 뒤 저장해 주세요.');}
function clearRich(){loadingRich=true;selectedImage=null;richBaseline=null;const previous=rich;rich=null;try{previous?.destruct();}finally{$('#blocks').replaceChildren();if($('#image-tools').open)$('#image-tools').close();}}
function dateNotes(){const news=form.elements.category.value==='newsroom';$('#publication-label').textContent=news?'기사 발행일':'최초 게시일';$('#title-label').textContent=news?'기사 제목':'제목';$('#summary-note').textContent=news?'요약은 저장하며 뉴스룸 목록 카드에는 표시하지 않습니다.':'';$('#research-year').hidden=news;const hasDate=!!current.published_at;$('#date-note').textContent=hasDate?(news?'기사 발행일':'최초 게시일')+' (한국 시간). 일반 저장 시 원래 시각을 유지합니다.':current.id?'원래 게시일 미확인 — 확인한 경우에만 입력하세요.':'새 글의 최초 게시일입니다. 게시 전에 확인해 주세요.';$('#modified-note').textContent=current.updated_at?'최근 수정: '+new Date(current.updated_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'';}
async function editorAPI(data){await refresh();const r=await fetch('/api/editor',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify(data)});const value=await r.json();if(!r.ok)throw new Error(value.error||'요청에 실패했습니다.');return value;}
function syncRich(){requireReady();if(rich.value!==richBaseline){blocks=htmlToTree(rich.value,v=>{for(const [path,url] of urls)if(v===url)return '/api/content?action=asset&path='+encodeURIComponent(path);return v;});}}
const msg=(text,error=false)=>{const el=$('#message');el.textContent=text;el.classList.toggle('cms-error',error);};
const sessionKey='giunchan-cms-session';
function remember(data){session={access_token:data.access_token,refresh_token:data.refresh_token,expires_at:data.expires_at||Math.floor(Date.now()/1000)+data.expires_in};sessionStorage.setItem(sessionKey,JSON.stringify(session));}
async function request(resource,options={},token=true){if(!config?.url||!config?.key)throw new Error('홈페이지 연결 정보를 확인해 주세요.');if(token)await refresh();const r=await fetch(config.url+resource,{...options,headers:{apikey:config.key,...(token&&session?{Authorization:'Bearer '+session.access_token}:{}),...options.headers}});if(!r.ok){if(r.status===401&&token){sessionStorage.removeItem(sessionKey);session=null;showLogin();}throw new Error(r.status===401?'로그인이 만료됐습니다. 다시 로그인해 주세요.':r.status===403?'접근 권한이 없습니다.':'요청에 실패했습니다. 입력 내용과 연결을 확인해 주세요.');}if(r.status===204)return null;return r;}
async function refresh(){if(!session)throw new Error('로그인해 주세요.');if(session.expires_at>Date.now()/1000+60)return;if(!refreshing)refreshing=(async()=>{const r=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})},false);remember(await r.json());})().finally(()=>refreshing=null);await refreshing;}
async function rows(resource,options){const r=await request('/rest/v1/'+resource,options);return r?await r.json():[];}
function showLogin(){$('#login-panel').hidden=false;$('#dashboard').hidden=true;$('#editor').hidden=true;$('#logout').hidden=true;}
async function enter(){const user=await(await request('/auth/v1/user')).json();const admins=await rows('content_admins?user_id=eq.'+user.id+'&select=user_id');if(!admins.length)throw new Error('이 계정에는 관리자 권한이 없습니다.');$('#login-panel').hidden=true;$('#logout').hidden=false;await showList();}
async function run(action){if(busy)return;busy=true;const controls=[...document.querySelectorAll('button,input[type=file]')];controls.forEach(b=>b.disabled=true);try{await action();}catch(e){msg(e.message,true);}finally{busy=false;controls.forEach(b=>b.disabled=false);applyEditorState();}}
async function getImage(object,variants=current?.details?.image_variants){if(!object)return '';if(object.startsWith('/assets/')||/^https?:\/\//.test(object))return object;if(urls.has(object))return urls.get(object);const chosen=variants?.[object]?.body?.path||object;const r=await request('/storage/v1/object/authenticated/content-assets/'+chosen.split('/').map(encodeURIComponent).join('/'));const url=URL.createObjectURL(await r.blob());urls.set(object,url);return url;}
async function showList(){dirty=false;$('#editor').hidden=true;$('#dashboard').hidden=false;posts=await rows('posts?select=*&order=updated_at.desc&limit='+Math.max(100,posts.length)+'&offset=0');$('#load-more').hidden=posts.length<100;await listCards();msg('');}
async function listCards(){const container=$('#post-list');container.replaceChildren();const selected=posts.filter(p=>(!$('#filter-category').value||p.category===$('#filter-category').value)&&(!$('#filter-status').value||p.status===$('#filter-status').value)&&p.title.includes($('#search').value));if(!selected.length){container.textContent='표시할 글이 없습니다.';return;}for(const p of selected){const card=document.createElement('article');card.className='cms-card';const image=p.thumbnail_path?await getImage(p.thumbnail_path,p.details?.image_variants):'';card.innerHTML=`${image?`<img src="${escape(image)}" alt="${escape(p.thumbnail_alt)}">`:'<div class="cms-no-image">GIUNCHAN</div>'}<div><span>${escape(categories[p.category])} · ${escape({draft:'초안',published:'게시됨',archived:'휴지통'}[p.status])}</span><h2>${escape(p.title)}</h2><p>${escape(p.summary)}</p><button type="button">수정하기</button></div>`;card.querySelector('button').onclick=()=>run(()=>edit(p));container.append(card);}}
function fields(){const fd=new FormData(form);return Object.fromEntries(fd.entries());}
function payload(status){syncRich();const f=fields();return {title:f.title.trim(),slug:f.slug.trim(),category:f.category,summary:f.summary,author:f.author,thumbnail_path:current.thumbnail_path||null,thumbnail_alt:f.thumbnail_alt,published_at:f.published_at===seoulDate(current.published_at)?current.published_at||null:f.published_at?new Date(f.published_at+'T00:00:00+09:00').toISOString():null,status,content:{...current.content,version:2,blocks},seo_title:f.seo_title||null,seo_description:f.seo_description||null,tags:f.tags.split(',').map(t=>t.trim()).filter(Boolean),details:{...(current.details||{}),subtype:f.subtype,publisher:f.publisher,source_url:f.source_url,journal:f.journal,year:f.year,doi:f.doi,ever_published:current.details?.ever_published||status==='published',attachments:assets.filter(a=>a.kind==='pdf').map(a=>a.storage_path)}};}
async function save(status,quiet=false){requireReady();if(!form.reportValidity())throw new Error('제목·글 주소·게시일을 확인해 주세요.');if(current.id&&current.slug!==fields().slug&&current.details?.ever_published)throw new Error('게시된 글의 주소는 유지해 주세요.');if(config.reservedSlugs?.includes(fields().slug)&&!(current.id&&current.slug===fields().slug&&config.migratedSlugs?.includes(current.slug)&&current.details?.migration?.slug===current.slug))throw new Error('기존 홈페이지 글과 주소가 겹칩니다. 다른 주소를 입력해 주세요.');const data=payload(status);if(current.details?.migration&&data.title!==current.title){const visit=n=>{if(n.tag==='h1')n.children=data.title.split(/(GMK®)/).filter(Boolean).map(t=>t==='GMK®'?{type:'element',tag:'span',attrs:{class:'no-break'},children:[{type:'text',text:'GMK'},{type:'element',tag:'sup',attrs:{class:'registered-mark'},children:[{type:'text',text:'®'}]}]}:{type:'text',text:t});for(const child of n.children||[])visit(child);};blocks.forEach(visit);}let result=await editorAPI({action:'save',id:current.id,updated_at:current.updated_at,post:data});if(!result.length)throw new Error('다른 창에서 글이 변경됐습니다. 목록에서 다시 열어 주세요.');current=result[0];dateNotes();richBaseline=rich?.value;dirty=false;$('#archive').hidden=false;form.elements.slug.readOnly=!!current.details?.ever_published;if(!quiet)msg(status==='published'?'게시했습니다. 홈페이지에서 확인해 주세요.':status==='archived'?'휴지통으로 이동했습니다.':'초안을 저장했습니다.');}
function bodyLoadFailed(error){
 console.error('[cms-editor-load]',{slug:current?.slug,phase:loadPhase,error});
 try{clearRich();}catch(cleanup){console.error('[cms-editor-cleanup]',cleanup);}
 loadingRich=false;bodyState='error';dirty=false;
 $('#body-load-error').hidden=false;
 $('#body-load-message').textContent=confirmedPost?'본문을 불러오지 못했습니다. 서버에서 기존 본문을 확인했으며, 이 작업으로 저장된 내용은 변경되지 않았습니다. 다시 불러오거나 목록으로 이동해 주세요.':'본문을 불러오지 못했습니다. 서버의 현재 내용을 확인하지 못했습니다. 연결을 확인한 뒤 다시 불러와 주세요.';
 msg('본문을 불러오지 못해 저장·게시를 사용할 수 없습니다.',true);applyEditorState();
}
async function edit(post){
 bodyState='loading';loadPhase='reset';confirmedPost=false;dirty=false;current=post?structuredClone(post):{status:'draft',thumbnail_path:null};initialPost=structuredClone(post);
 $('#body-load-error').hidden=true;$('#dashboard').hidden=true;$('#editor').hidden=false;msg('본문을 불러오는 중입니다.');applyEditorState();
 try{
  clearRich();form.reset();urls.forEach(u=>URL.revokeObjectURL(u));urls.clear();blocks=[];assets=[];
  if(post?.id){loadPhase='fetch-post';const latest=await rows('posts?id=eq.'+post.id+'&select=*');if(latest.length!==1)throw new Error('게시글을 조회하지 못했습니다.');current=structuredClone(latest[0]);initialPost=structuredClone(current);confirmedPost=Array.isArray(current.content?.blocks);if(!confirmedPost)throw new Error('저장된 본문 구조가 올바르지 않습니다.');}
  blocks=structuredClone(current.content?.blocks||[{type:'paragraph',text:''}]);
  for(const key of ['title','slug','category','summary','author','thumbnail_alt','seo_title','seo_description'])if(current[key]!=null)form.elements[key].value=current[key];
  form.elements.published_at.required=!current.details?.migration?.date_unknown;
  form.elements.published_at.value=current.published_at?seoulDate(current.published_at):current.id?'':seoulDate(new Date());
  form.elements.tags.value=(current.tags||[]).join(', ');
  for(const [key,value] of Object.entries(current.details||{}))if(form.elements[key])form.elements[key].value=value;
  form.elements.slug.readOnly=!!current.details?.ever_published;$('#archive').hidden=!current.id;dateNotes();
  loadPhase='fetch-assets';assets=current.id?await rows('post_assets?post_id=eq.'+current.id):[];
  loadPhase='cover';await cover();await renderEditor();renderAttachments();dirty=false;
  msg(current.id&&!current.published_at?'원래 게시일을 확인할 수 없습니다. 확인한 날짜만 입력해 주세요.':'');
 }catch(error){bodyLoadFailed(error);}
}
form.elements.category.addEventListener('change',dateNotes);
$('#retry-body').onclick=()=>run(()=>edit(current));
async function cover(){const img=$('#cover-preview');img.hidden=!current.thumbnail_path;if(current.thumbnail_path)img.src=await getImage(current.thumbnail_path);else img.removeAttribute('src');}
async function renderEditor(){
 validateTree(blocks.filter(b=>['element','text'].includes(b.type)));if(blocks.some(b=>!['element','text','paragraph','heading','image','gallery','table','link','faq'].includes(b.type)))throw new Error('지원하지 않는 본문 요소가 있어 편집을 중단했습니다. 원문은 보존됩니다.');
 loadingRich=true;$('#blocks').innerHTML='<textarea id="rich-body" aria-label="본문 편집"></textarea>';
 loadPhase='jodit-initialize';rich=createRichEditor('#rich-body',{onChange:()=>{if(!loadingRich)dirty=true;},onImage:()=>chooseImages(false),onGallery:()=>chooseImages(true),onSelectImage:img=>{selectedImage=img;$('#image-tools').showModal();$('#image-alt').value=img.alt;$('#image-caption').value=img.closest('figure')?.querySelector('figcaption')?.textContent||'';}});
 loadPhase='render-content';rich.value=renderBlocks(blocks);
 loadPhase='body-images';for(const img of rich.editor.querySelectorAll('img')){const u=new URL(img.src,location.origin);if(u.pathname==='/api/content'&&u.searchParams.has('path'))img.src=await getImage(u.searchParams.get('path'));}
 richBaseline=rich.value;loadingRich=false;bodyState='ready';applyEditorState();
}
function chooseImages(gallery){rich.s.save();$('#body-images').multiple=gallery;$('#body-images').dataset.gallery=String(gallery);$('#body-images').click();}
$('#body-images').onchange=()=>run(async()=>{
 const files=[...$('#body-images').files],gallery=$('#body-images').dataset.gallery==='true';if(files.length>(gallery?3:1))throw new Error('이미지 모음은 최대 3장입니다.');
 const parts=[];for(const file of files){const a=await uploadAsset(file,'image');parts.push(`<figure><img src="${escape(await getImage(a.storage_path))}" alt="" width="${a.variants.body.width}" height="${a.variants.body.height}"><figcaption></figcaption></figure>`);}
 rich.s.restore();rich.s.insertHTML(gallery?'<div class="cms-gallery">'+parts.join('')+'</div>':parts.join(''));dirty=true;$('#body-images').value='';
});
$('#image-apply').onclick=()=>{if(!selectedImage)return;selectedImage.alt=$('#image-alt').value;let figure=selectedImage.closest('figure');if(!figure){figure=document.createElement('figure');selectedImage.replaceWith(figure);figure.append(selectedImage);}let cap=figure.querySelector('figcaption');if(!cap){cap=document.createElement('figcaption');figure.append(cap);}cap.textContent=$('#image-caption').value;cap.removeAttribute('style');rich.synchronizeValues();dirty=true;$('#image-tools').close();};
$('#image-delete').onclick=()=>{if(selectedImage){(selectedImage.closest('figure')||selectedImage).remove();rich.synchronizeValues();dirty=true;$('#image-tools').close();}};
$('#add-faq').onclick=()=>{rich.s.insertHTML('<details open><summary>질문을 입력하세요</summary><p>답변을 입력하세요</p></details>');dirty=true;};
$('#backup-post').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(initialPost||current,null,2)],{type:'application/json'}));a.download=(current.slug||'new')+'-backup.json';a.click();URL.revokeObjectURL(a.href);};
$('#restore-post').onchange=()=>run(async()=>{const p=JSON.parse(await $('#restore-post').files[0].text());if(p.id!==current.id||!Array.isArray(p.content?.blocks))throw new Error('현재 글의 백업 파일을 선택하세요.');blocks=structuredClone(p.content.blocks);try{clearRich();await renderEditor();dirty=true;msg('백업 본문을 불러왔습니다. 저장 전에는 DB가 변경되지 않습니다.');}catch(error){bodyLoadFailed(error);}});
async function uploadAsset(file,kind){if(!file)return;if(file.size>20*1024*1024)throw new Error('파일은 20MB 이하로 올려 주세요.');if(kind==='pdf'?file.type!=='application/pdf':!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw new Error('지원하지 않는 파일 형식입니다.');if(!current.id)await save('draft',true);const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif','application/pdf':'pdf'}[file.type];const object=current.id+'/'+crypto.randomUUID()+'.'+extension;await request('/storage/v1/object/content-assets/'+object,{method:'POST',headers:{'Content-Type':file.type,'cache-control':'max-age=31536000'},body:file});const result=await rows('post_assets',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify({post_id:current.id,storage_path:object,original_name:file.name,kind})});assets.push(result[0]);if(kind==='image'){msg('웹용 이미지 최적화 중… 원본은 보존됩니다.');const variants=await editorAPI({action:'optimize',path:object});current.details||={};current.details.image_variants||={};current.details.image_variants[object]=variants;result[0].variants=variants;}msg('파일을 올렸습니다. 변경한 본문과 대표 이미지는 저장 또는 게시 버튼으로 반영해 주세요.');return result[0];}
function renderAttachments(){const ul=$('#attachments');ul.replaceChildren();for(const a of assets.filter(a=>a.kind==='pdf')){const li=document.createElement('li');li.textContent=a.original_name+' ';const button=document.createElement('button');button.type='button';button.textContent='첨부 제외';button.onclick=()=>run(async()=>{await rows('post_assets?id=eq.'+a.id,{method:'DELETE'});assets=assets.filter(item=>item.id!==a.id);renderAttachments();msg('첨부파일 연결을 해제했습니다.');});li.append(button);ul.append(li);}}
$('#login-form').onsubmit=e=>{e.preventDefault();run(async()=>{const r=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#password').value})},false);remember(await r.json());$('#password').value='';await enter();});};
$('#logout').onclick=()=>run(async()=>{try{await request('/auth/v1/logout',{method:'POST'});}finally{session=null;sessionStorage.removeItem(sessionKey);urls.forEach(u=>URL.revokeObjectURL(u));urls.clear();showLogin();msg('로그아웃했습니다.');}});
$('#new-post').onclick=()=>run(()=>edit());$('#back-bottom').onclick=()=>$('#back').click();$('#back').onclick=()=>{if(!dirty||confirm('저장하지 않은 변경이 있습니다. 목록으로 돌아갈까요?'))run(showList);};
$('#load-more').onclick=()=>run(async()=>{const next=await rows('posts?select=*&order=updated_at.desc&limit=100&offset='+posts.length);posts.push(...next);$('#load-more').hidden=next.length<100;await listCards();});
for(const selector of ['#filter-category','#filter-status','#search'])$(selector).oninput=()=>run(listCards);
form.oninput=()=>dirty=true;form.onsubmit=e=>{e.preventDefault();run(()=>save('published'));};$('#save-draft').onclick=()=>run(()=>save('draft'));$('#archive').onclick=()=>{if(confirm('이 글을 비공개로 전환하고 휴지통으로 옮길까요?'))run(()=>save('archived'));};
$('#cover-upload').onchange=()=>run(async()=>{const a=await uploadAsset($('#cover-upload').files[0],'image');current.thumbnail_path=a.storage_path;dirty=true;await cover();});$('#remove-cover').onclick=()=>{current.thumbnail_path=null;dirty=true;cover();};$('#pdf-upload').onchange=()=>run(async()=>{await uploadAsset($('#pdf-upload').files[0],'pdf');renderAttachments();$('#pdf-upload').value='';});
$('#preview').onclick=()=>run(async()=>{if(!form.reportValidity())return;const p=payload(current.status);const body=$('#preview-body');body.innerHTML=`<h1>${escape(p.title)}</h1><p class="cms-summary">${escape(p.summary)}</p>${p.thumbnail_path?`<img class="cms-cover" src="${escape(await getImage(p.thumbnail_path,p.details?.image_variants))}" alt="${escape(p.thumbnail_alt)}">`:''}${renderBlocks(p.content.blocks)}`;for(const img of body.querySelectorAll('img')){const u=new URL(img.src);if(u.searchParams.has('path'))img.src=await getImage(u.searchParams.get('path'));}$('#preview-dialog').showModal();});$('#preview-close').onclick=()=>$('#preview-dialog').close();$('#preview-width').onchange=()=>$('#preview-body').style.maxWidth=$('#preview-width').value;
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
try{const r=await fetch('/api/content?action=config');if(r.ok){const loaded=await r.json();if(!loaded?.url||!loaded?.key)throw new Error('홈페이지 연결 정보가 올바르지 않습니다.');config=loaded;}else{const reserved=await fetch('/cms-reserved.json');if(!reserved.ok)throw new Error('홈페이지 연결 정보를 불러오지 못했습니다. 새로고침해 주세요.');config={...publicCMSConfig,reservedSlugs:await reserved.json()};}try{session=JSON.parse(sessionStorage.getItem(sessionKey));}catch{session=null;}if(session)await enter();}catch(e){showLogin();msg(e.message,true);}

$('#optimize-existing').onclick=()=>run(async()=>{if(!current.id)throw new Error('먼저 글을 저장해 주세요.');const images=assets.filter(a=>a.kind==='image'&&!/\.(thumb|body)-v1\.webp$/.test(a.storage_path));for(let i=0;i<images.length;i++){msg(`기존 이미지 최적화 ${i+1}/${images.length} — 원본 보존`);const path=images[i].storage_path;const variants=await editorAPI({action:'optimize',path});current.details||={};current.details.image_variants||={};current.details.image_variants[path]=variants;}dirty=true;msg('최적화 완료. 저장하면 웹용 파일이 적용됩니다. 원본은 보존됩니다.');});

$('#image-close').onclick=()=>$('#image-tools').close();
